Here is the commit message:
pmdomain: mediatek: fix use-after-free in
 scpsys_get_bus_protection_legacy()

In scpsys_get_bus_protection_legacy(), of_find_node_with_property()
returns a device node with its reference count incremented. The function
then calls of_node_put(node) before checking whether
syscon_regmap_lookup_by_phandle() returns an error. If an error occurs,
dev_err_probe() dereferences the node pointer to print diagnostic
information, but the node memory may have already been freed due to the
earlier of_node_put(), leading to a use-after-free vulnerability.

Fix this by moving the of_node_put() call after the error check, ensuring
the node is still valid when accessed in the error path.

Fixes: c29345fa5f66 ("pmdomain: mediatek: Refactor bus protection regmaps retrieval")
Cc: stable@vger.kernel.org
Signed-off-by: Wentao Liang <vulab@iscas.ac.cn>
Signed-off-by: Ulf Hansson <ulf.hansson@linaro.org>

Here is the root cause:
In `scpsys_get_bus_protection_legacy()`, `of_node_put(node)` was called immediately after obtaining the regmap via `syscon_regmap_lookup_by_phandle()`, before checking if the returned regmap is an error pointer. When an error occurs, `dev_err_probe()` dereferences the `node` pointer to print diagnostic information, but the node may already have been freed due to the earlier `of_node_put()`, causing a use-after-free vulnerability. The fix reorders the operations to call `of_node_put()` only after the error check and handling.

Here is the patch:

 static int scpsys_get_bus_protection_legacy(struct device *dev, struct scpsys *scpsys)
 {
 	const u8 bp_blocks[3] = {
 		BUS_PROT_BLOCK_INFRA, BUS_PROT_BLOCK_SMI, BUS_PROT_BLOCK_INFRA_NAO
 	};
 	struct device_node *np = dev->of_node;
 	struct device_node *node, *smi_np;
 	int num_regmaps = 0, i, j;
 	struct regmap *regmap[3];
+	int ret = 0;

 	/*
 	 * Legacy code retrieves a maximum of three bus protection handles:
 	 * some may be optional, or may not be, so the array of bp blocks
 	 * that is normally passed in as platform data must be dynamically
 	 * built in this case.
 	 *
 	 * Here, try to retrieve all of the regmaps that the legacy code
 	 * supported and then count the number of the ones that are present,
 	 * this makes it then possible to allocate the array of bus_prot
 	 * regmaps and convert all to the new style handling.
 	 */
 	of_node_get(np);
 	node = of_find_node_with_property(np, "mediatek,infracfg");
 	if (node) {
 		regmap[0] = syscon_regmap_lookup_by_phandle(node, "mediatek,infracfg");
 		of_node_put(node);
 		num_regmaps++;
 		if (IS_ERR(regmap[0]))
 			return dev_err_probe(dev, PTR_ERR(regmap[0]),
 					     "%pOF: failed to get infracfg regmap\n",
 					     node);
 	} else {
 		regmap[0] = NULL;
 	}

 	of_node_get(np);
 	node = of_find_node_with_property(np, "mediatek,smi");
 	if (node) {
 		smi_np = of_parse_phandle(node, "mediatek,smi", 0);
 		of_node_put(node);
 		if (!smi_np)
 			return -ENODEV;

 		regmap[1] = device_node_to_regmap(smi_np);
 		num_regmaps++;
 		of_node_put(smi_np);
 		if (IS_ERR(regmap[1]))
 			return dev_err_probe(dev, PTR_ERR(regmap[1]),
 					     "%pOF: failed to get SMI regmap\n",
 					     node);
 	} else {
 		regmap[1] = NULL;
 	}

 	of_node_get(np);
 	node = of_find_node_with_property(np, "mediatek,infracfg-nao");
 	if (node) {
 		regmap[2] = syscon_regmap_lookup_by_phandle(node, "mediatek,infracfg-nao");
 		num_regmaps++;
-		of_node_put(node);
-		if (IS_ERR(regmap[2]))
-			return dev_err_probe(dev, PTR_ERR(regmap[2]),
+		if (IS_ERR(regmap[2])) {
+			ret = dev_err_probe(dev, PTR_ERR(regmap[2]),
 					     "%pOF: failed to get infracfg regmap\n",
 					     node);
+			of_node_put(node);
+			return ret;
+		}
+		of_node_put(node);
 	} else {
 		regmap[2] = NULL;
 	}

 	scpsys->bus_prot = devm_kmalloc_array(dev, num_regmaps,
 					      sizeof(*scpsys->bus_prot), GFP_KERNEL);
 	if (!scpsys->bus_prot)
 		return -ENOMEM;

 	for (i = 0, j = 0; i < ARRAY_SIZE(bp_blocks); i++) {
 		enum scpsys_bus_prot_block bp_type;

 		if (!regmap[i])
 			continue;

 		bp_type = bp_blocks[i];
 		scpsys->bus_prot_index[bp_type] = j;
 		scpsys->bus_prot[j] = regmap[i];

 		j++;
 	}

 	return 0;
 }



